package com.slayerclog;

import com.google.inject.Provides;
import com.slayerclog.clog.CollectionLogManager;
import com.slayerclog.task.ItemGroup;
import com.slayerclog.task.MonsterMapping;
import com.slayerclog.task.MortimerInterfaceHandler;
import com.slayerclog.task.SlayerMonster;
import com.slayerclog.task.SlayerTaskTracker;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
	name = "Slayer Clog Check",
	description = "Shows collection log progress for your current slayer task, and compares each option at Mortimer.",
	tags = {"slayer", "collection", "log", "clog", "task", "mortimer", "skip"}
)
public class SlayerClogPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SlayerClogConfig config;

	@Inject
	private CollectionLogManager clogManager;

	@Inject
	private MonsterMapping mapping;

	@Inject
	private SlayerTaskTracker taskTracker;

	@Inject
	private MortimerInterfaceHandler mortimer;

	private SlayerClogPanel panel;
	private NavigationButton navButton;

	// Chest rewards: Konar tasks give Brimstone keys, Krystilia's wilderness tasks give Larran's keys.
	// mapping label for a task's shared superior drops
	private static final String SUPERIOR_LABEL = "Superior";
	private static final String BRIMSTONE_CHEST = "Brimstone chest";
	private static final String LARRANS_CHEST = "Larran's chest";
	private static final int KRYSTILIA_SLAYER_MASTER = 7;

	// Mortimer state
	private boolean mortimerActive;
	private List<String> mortimerOptions;

	// Task polling state
	private String lastTaskName;
	private int lastAmount = -1;

	// "New item added to your collection log: <name>."
	private static final Pattern CLOG_MESSAGE = Pattern.compile(
		"added to your collection log:\\s*(.+)", Pattern.CASE_INSENSITIVE);
	private final Map<String, Integer> itemNameToId = new HashMap<>();
	private boolean nameIndexBuilt;

	@Provides
	SlayerClogConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerClogConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new SlayerClogPanel(itemManager, config);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/slayerclog/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Slayer Clog Check")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() ->
			{
				clogManager.load(client.getAccountHash());
				refreshView();
			});
		}
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		mortimerActive = false;
		mortimerOptions = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clogManager.load(client.getAccountHash());
			refreshView();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST)
		{
			clogManager.captureOpenPage();
			refreshView();
		}
	}

	/** Ticks an item as soon as the new collection log item message fires. */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final String message = event.getMessage();
		if (message == null)
		{
			return;
		}
		final Matcher m = CLOG_MESSAGE.matcher(message);
		if (!m.find())
		{
			return;
		}
		final String itemName = m.group(1).replaceAll("<[^>]*>", "").replaceAll("[.\\s]+$", "").trim();
		ensureNameIndex();
		final Integer id = itemNameToId.get(itemName.toLowerCase());
		if (id != null)
		{
			clogManager.markObtained(id);
			refreshView();
		}
	}

	/** Builds a name to item id index. Client thread only. */
	private void ensureNameIndex()
	{
		if (nameIndexBuilt)
		{
			return;
		}
		for (int id : mapping.allItemIds())
		{
			try
			{
				final String name = itemManager.getItemComposition(id).getName();
				if (name != null && !name.isEmpty())
				{
					itemNameToId.put(name.toLowerCase(), id);
				}
			}
			catch (Exception ignored)
			{
				// no composition
			}
		}
		nameIndexBuilt = true;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// Poll for the Mortimer interface; it does not reliably emit WidgetLoaded.
		if (config.mortimerView())
		{
			final List<String> opts = mortimer.detect(MortimerInterfaceHandler.MORTIMER_GROUP_ID);
			if (!opts.isEmpty())
			{
				if (!mortimerActive || !opts.equals(mortimerOptions))
				{
					mortimerActive = true;
					mortimerOptions = opts;
					refreshView();
				}
				return;
			}
			if (mortimerActive)
			{
				mortimerActive = false;
				mortimerOptions = null;
				refreshView();
			}
		}

		// Poll the task, stored as per-profile config.
		final String name = taskTracker.getCurrentTaskName();
		final int amount = taskTracker.getAmount();
		if (!Objects.equals(name, lastTaskName) || amount != lastAmount)
		{
			lastTaskName = name;
			lastAmount = amount;
			refreshView();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SlayerClogConfig.GROUP.equals(event.getGroup()))
		{
			refreshView();
		}
	}

	/** Rebuilds the panel: data on the client thread, UI on the EDT. */
	private void refreshView()
	{
		if (panel == null)
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			if (mortimerActive && mortimerOptions != null && config.mortimerView())
			{
				final List<SlayerClogPanel.Option> options = new ArrayList<>();
				for (String optionName : mortimerOptions)
				{
					final SlayerMonster monster = mapping.get(optionName);
					final List<SlayerClogPanel.Section> sections =
						monster == null ? new ArrayList<>() : buildSections(monster);
					options.add(new SlayerClogPanel.Option(optionName, sections));
				}
				updatePanel(() -> panel.showMortimer(options));
				return;
			}

			final String taskName = taskTracker.getCurrentTaskName();
			if (taskName == null)
			{
				updatePanel(() -> panel.showMessage(
					"No active slayer task.", "Get a slayer task to see its collection log progress."));
				return;
			}

			final int amount = taskTracker.getAmount();
			final String location = taskTracker.getTaskLocation();
			final SlayerMonster monster = mapping.get(taskName);
			final List<SlayerClogPanel.Section> sections =
				monster == null ? new ArrayList<>() : buildSections(monster);
			if (location != null)
			{
				addChest(sections, BRIMSTONE_CHEST);
			}
			if (client.getVarbitValue(VarbitID.SLAYER_MASTER) == KRYSTILIA_SLAYER_MASTER)
			{
				addChest(sections, LARRANS_CHEST);
			}
			updatePanel(() -> panel.showTask(taskName, amount, location, sections));
		});
	}

	/** One section per monster version. Client thread only. */
	private List<SlayerClogPanel.Section> buildSections(SlayerMonster monster)
	{
		final List<SlayerClogPanel.Section> sections = new ArrayList<>();
		for (ItemGroup group : monster.getGroups())
		{
			if (!config.showSuperior() && SUPERIOR_LABEL.equals(group.getMonster()))
			{
				continue;
			}
			final List<SlayerClogPanel.ItemRow> rows = new ArrayList<>();
			for (int itemId : group.getItems())
			{
				final String name = itemManager.getItemComposition(itemId).getName();
				final Boolean status = clogManager.isObtained(group.getPage(), itemId);
				final boolean synced = status != null;
				final boolean obtained = Boolean.TRUE.equals(status);
				final int quantity = clogManager.getQuantity(group.getPage(), itemId);
				final String rate = group.getRates().get(itemId);
				rows.add(new SlayerClogPanel.ItemRow(itemId, name, obtained, quantity, synced, rate));
			}
			sections.add(new SlayerClogPanel.Section(group.getMonster(), rows));
		}
		return sections;
	}

	/** Adds a chest entry from the mapping as extra sections. */
	private void addChest(List<SlayerClogPanel.Section> sections, String key)
	{
		final SlayerMonster chest = mapping.get(key);
		if (chest != null)
		{
			sections.addAll(buildSections(chest));
		}
	}

	private void updatePanel(Runnable update)
	{
		final SlayerClogPanel current = panel;
		if (current == null)
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (panel == current)
			{
				update.run();
			}
		});
	}
}

package com.slayerclog;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import lombok.Value;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

/** Sidebar panel. All methods must be called on the EDT. */
class SlayerClogPanel extends PluginPanel
{
	/** One item row. */
	@Value
	static class ItemRow
	{
		int itemId;
		String name;
		boolean obtained;
		int quantity;
		boolean synced;
		// drop rate, or null when unknown
		String rate;
	}

	/** One monster version and its rows. */
	@Value
	static class Section
	{
		String monster;
		List<ItemRow> rows;
	}

	/** A Mortimer option. */
	@Value
	static class Option
	{
		String name;
		List<Section> sections;
	}

	private static final Color OBTAINED = new Color(76, 175, 80);
	private static final Color MISSING = new Color(160, 160, 160);
	private static final Color WARN = new Color(220, 138, 0);

	private final ItemManager itemManager;
	private final SlayerClogConfig config;
	private final JPanel content = new JPanel();

	SlayerClogPanel(ItemManager itemManager, SlayerClogConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		add(content, BorderLayout.NORTH);

		showMessage("No active slayer task.", "Get a slayer task to see its collection log progress.");
	}

	void showMessage(String title, String subtitle)
	{
		content.removeAll();
		content.add(titleLabel(title));
		if (subtitle != null)
		{
			content.add(wrappedText(subtitle, MISSING));
		}
		refresh();
	}

	/** Current task, per monster version. */
	void showTask(String taskName, int amount, String location, List<Section> sections)
	{
		content.removeAll();
		content.add(titleLabel(amount > 0 ? taskName + " (" + amount + ")" : taskName));
		if (location != null)
		{
			content.add(wrappedText(location, MISSING));
		}

		if (sections.isEmpty())
		{
			content.add(wrappedText("No collection log items are mapped for this task yet.", MISSING));
			refresh();
			return;
		}

		final List<ItemRow> all = new ArrayList<>();
		for (Section section : sections)
		{
			all.addAll(section.getRows());
			content.add(sectionPanel(section));
		}

		content.add(wrappedText(skipHint(all), MISSING));
		refresh();
	}

	/** Mortimer option comparison. */
	void showMortimer(List<Option> options)
	{
		content.removeAll();
		content.add(titleLabel("Mortimer"));
		content.add(wrappedText("Compare what each option can add to your collection log:", MISSING));

		for (Option option : options)
		{
			final JPanel card = new JPanel();
			card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
			card.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
				BorderFactory.createEmptyBorder(6, 0, 6, 0)));
			card.setAlignmentX(Component.LEFT_ALIGNMENT);

			final JLabel name = new JLabel(plain(option.getName()));
			name.setFont(FontManager.getRunescapeBoldFont());
			name.setForeground(Color.WHITE);
			name.setAlignmentX(Component.LEFT_ALIGNMENT);
			card.add(name);

			if (option.getSections().isEmpty())
			{
				card.add(wrappedText("No collection log items found.", MISSING));
			}
			else
			{
				for (Section section : option.getSections())
				{
					card.add(sectionPanel(section));
				}
			}
			content.add(card);
		}
		refresh();
	}

	/** Monster sub-header plus its item rows. */
	private JPanel sectionPanel(Section section)
	{
		final JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBorder(BorderFactory.createEmptyBorder(4, 0, 2, 0));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		int obtained = 0;
		boolean anyUnsynced = false;
		for (ItemRow row : section.getRows())
		{
			if (row.isObtained())
			{
				obtained++;
			}
			if (!row.isSynced())
			{
				anyUnsynced = true;
			}
		}

		final JPanel head = new JPanel(new BorderLayout());
		head.setAlignmentX(Component.LEFT_ALIGNMENT);
		final JLabel monster = new JLabel(plain(section.getMonster()));
		monster.setFont(FontManager.getRunescapeSmallFont());
		monster.setForeground(new Color(200, 200, 200));
		head.add(monster, BorderLayout.WEST);
		final JLabel count = new JLabel(obtained + " / " + section.getRows().size());
		count.setFont(FontManager.getRunescapeSmallFont());
		count.setForeground(obtained == section.getRows().size() && !anyUnsynced ? OBTAINED : MISSING);
		head.add(count, BorderLayout.EAST);
		panel.add(head);

		for (ItemRow row : section.getRows())
		{
			if (config.showOnlyUnobtained() && row.isObtained())
			{
				continue;
			}
			panel.add(itemRow(row));
		}
		if (anyUnsynced)
		{
			panel.add(wrappedText("Open this monster's collection log page to sync.", WARN));
		}
		return panel;
	}

	private JPanel itemRow(ItemRow row)
	{
		final JPanel panel = new JPanel(new BorderLayout(6, 0));
		panel.setBorder(BorderFactory.createEmptyBorder(1, 6, 1, 0));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		final AsyncBufferedImage image = itemManager.getImage(row.getItemId());
		image.addTo(icon);
		panel.add(icon, BorderLayout.WEST);

		final JLabel name = new JLabel(plain(row.getName()));
		name.setForeground(row.isObtained() ? Color.WHITE : MISSING);

		final String rate = row.getRate();
		if (config.showDropRates() && rate != null && !rate.isEmpty())
		{
			// drop rate on a second line under the name
			final JPanel labels = new JPanel();
			labels.setLayout(new BoxLayout(labels, BoxLayout.Y_AXIS));
			name.setAlignmentX(Component.LEFT_ALIGNMENT);
			labels.add(name);

			final JLabel rateLabel = new JLabel(plain("(" + rate.replace('/', ':') + ")"));
			rateLabel.setFont(FontManager.getRunescapeSmallFont());
			rateLabel.setForeground(MISSING);
			rateLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
			labels.add(rateLabel);

			panel.add(labels, BorderLayout.CENTER);
		}
		else
		{
			panel.add(name, BorderLayout.CENTER);
		}

		final JLabel status = new JLabel();
		if (!row.isSynced())
		{
			status.setText("?");
			status.setForeground(WARN);
		}
		else if (row.isObtained())
		{
			status.setText(config.showQuantities() && row.getQuantity() > 0 ? "✓ " + row.getQuantity() : "✓");
			status.setForeground(OBTAINED);
		}
		else
		{
			status.setText("✗");
			status.setForeground(MISSING);
		}
		panel.add(status, BorderLayout.EAST);
		return panel;
	}

	private static String skipHint(List<ItemRow> rows)
	{
		boolean anyUnsynced = false;
		boolean anyMissing = false;
		for (ItemRow row : rows)
		{
			if (!row.isSynced())
			{
				anyUnsynced = true;
			}
			else if (!row.isObtained())
			{
				anyMissing = true;
			}
		}
		if (anyUnsynced)
		{
			return "Sync your collection log for a complete picture.";
		}
		return anyMissing
			? "You are still missing log items"
			: "All collection log items collected";
	}

	private static JLabel titleLabel(String text)
	{
		final JLabel label = new JLabel(plain(text));
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JLabel wrappedText(String text, Color color)
	{
		final JLabel label = new JLabel("<html><body style='width:150px'>" + escapeHtml(text) + "</body></html>");
		label.setForeground(color);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/** Strips angle brackets so Swing cannot treat the text as HTML. */
	private static String plain(String text)
	{
		return text == null ? "" : text.replace("<", "").replace(">", "");
	}

	/** Escapes text embedded in wrappedText's HTML. */
	private static String escapeHtml(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private void refresh()
	{
		content.revalidate();
		content.repaint();
	}
}

package com.slayerclog.task;

import java.util.List;
import lombok.Value;

/** A slayer task and its per-monster clog sections. */
@Value
public class SlayerMonster
{
	String name;
	List<ItemGroup> groups;
}

package com.slayerclog.task;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

/** Reads the current slayer task from the Slayer plugin's per-profile config. */
@Singleton
public class SlayerTaskTracker
{
	public static final String SLAYER_CONFIG_GROUP = "slayer";
	public static final String TASK_NAME_KEY = "taskName";
	public static final String AMOUNT_KEY = "amount";
	public static final String TASK_LOC_KEY = "taskLocation";

	private final ConfigManager configManager;

	@Inject
	private SlayerTaskTracker(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	/** Current task name, or null if none. */
	public String getCurrentTaskName()
	{
		final String name = configManager.getRSProfileConfiguration(SLAYER_CONFIG_GROUP, TASK_NAME_KEY);
		if (name == null || name.isEmpty() || "None".equalsIgnoreCase(name))
		{
			return null;
		}
		return name;
	}

	/** Remaining kill count. */
	public int getAmount()
	{
		final String amount = configManager.getRSProfileConfiguration(SLAYER_CONFIG_GROUP, AMOUNT_KEY);
		if (amount == null)
		{
			return 0;
		}
		try
		{
			return Integer.parseInt(amount);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** Assigned area, or null. Only Konar sets one. */
	public String getTaskLocation()
	{
		final String location = configManager.getRSProfileConfiguration(SLAYER_CONFIG_GROUP, TASK_LOC_KEY);
		return location == null || location.isEmpty() ? null : location;
	}
}

package com.slayerclog.task;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;

/** Reads the task options from Mortimer's "Slayer Task Choice" interface. */
@Singleton
public class MortimerInterfaceHandler
{
	/** "Slayer Task Choice" interface group id. */
	public static final int MORTIMER_GROUP_ID = 236;

	private final Client client;

	@Inject
	private MortimerInterfaceHandler(Client client)
	{
		this.client = client;
	}

	/** Offered monster names, or empty if the interface is not open. Client thread only. */
	public List<String> detect(int loadedGroupId)
	{
		if (loadedGroupId != MORTIMER_GROUP_ID)
		{
			return Collections.emptyList();
		}

		final List<String> names = new ArrayList<>();
		final Set<String> seen = new HashSet<>();

		for (int child = 0; child <= 5; child++)
		{
			collect(client.getWidget(loadedGroupId, child), names, seen);
		}

		return names;
	}

	private void collect(Widget widget, List<String> names, Set<String> seen)
	{
		if (widget == null)
		{
			return;
		}

		final String text = widget.getText();
		// Option names are the underlined links.
		if (text != null && text.contains("<u="))
		{
			final String name = text.replaceAll("<[^>]*>", "").trim();
			if (!name.isEmpty() && seen.add(name.toLowerCase()))
			{
				names.add(name);
			}
		}

		collectAll(widget.getStaticChildren(), names, seen);
		collectAll(widget.getDynamicChildren(), names, seen);
		collectAll(widget.getNestedChildren(), names, seen);
	}

	private void collectAll(Widget[] children, List<String> names, Set<String> seen)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			collect(child, names, seen);
		}
	}
}

package com.slayerclog.task;

import java.util.List;
import java.util.Map;
import lombok.Value;

/** One monster version and its clog items on a single page, with drop rates where known. */
@Value
public class ItemGroup
{
	String monster;
	String page;
	List<Integer> items;
	// item id -> drop rate
	Map<Integer, String> rates;
}

package com.slayerclog.task;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Loads the bundled task -> collection log item mapping. */
@Slf4j
@Singleton
public class MonsterMapping
{
	private static final String RESOURCE = "/com/slayerclog/slayer_monster_items.json";

	/** JSON shape of a section. */
	private static final class RawGroup
	{
		String monster;
		String page;
		List<Integer> items;
		// JSON object keys are strings
		Map<String, String> rates;
	}

	private final Gson gson;

	private final Map<String, SlayerMonster> byName = new HashMap<>();

	@Inject
	MonsterMapping(Gson gson)
	{
		this.gson = gson;
		load();
	}

	private void load()
	{
		final Type outerType = new TypeToken<Map<String, JsonElement>>()
		{
		}.getType();
		final Type groupsType = new TypeToken<List<RawGroup>>()
		{
		}.getType();

		try (InputStream in = MonsterMapping.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.error("Could not find monster mapping resource {}", RESOURCE);
				return;
			}
			final Map<String, JsonElement> raw = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), outerType);
			if (raw == null)
			{
				return;
			}
			for (Map.Entry<String, JsonElement> e : raw.entrySet())
			{
				final String name = e.getKey();
				// Skip documentation keys.
				if (name.startsWith("_") || e.getValue() == null || !e.getValue().isJsonArray())
				{
					continue;
				}
				final List<RawGroup> rawGroups = gson.fromJson(e.getValue(), groupsType);
				final List<ItemGroup> groups = new ArrayList<>();
				for (RawGroup g : rawGroups)
				{
					if (g == null || g.items == null || g.items.isEmpty())
					{
						continue;
					}
					final String page = g.page == null ? "Slayer" : g.page;
					final String monster = g.monster == null ? name : g.monster;
					groups.add(new ItemGroup(monster, page,
						Collections.unmodifiableList(new ArrayList<>(g.items)),
						Collections.unmodifiableMap(parseRates(g.rates))));
				}
				if (!groups.isEmpty())
				{
					byName.put(normalize(name),
						new SlayerMonster(name, Collections.unmodifiableList(groups)));
				}
			}
		}
		catch (Exception ex)
		{
			log.error("Failed to load monster mapping", ex);
		}
	}

	/** Rates keyed by item id; non-numeric keys are skipped. */
	private static Map<Integer, String> parseRates(Map<String, String> raw)
	{
		final Map<Integer, String> rates = new HashMap<>();
		if (raw != null)
		{
			for (Map.Entry<String, String> e : raw.entrySet())
			{
				try
				{
					rates.put(Integer.parseInt(e.getKey().trim()), e.getValue());
				}
				catch (NumberFormatException ignored)
				{
					// not an item id
				}
			}
		}
		return rates;
	}

	/** All item ids in the mapping. */
	public Set<Integer> allItemIds()
	{
		final Set<Integer> ids = new HashSet<>();
		for (SlayerMonster m : byName.values())
		{
			for (ItemGroup g : m.getGroups())
			{
				ids.addAll(g.getItems());
			}
		}
		return ids;
	}

	/** Lookup by task name. */
	public SlayerMonster get(String name)
	{
		if (name == null)
		{
			return null;
		}
		return byName.get(normalize(name));
	}

	/** Lookup for free text, falling back to a contains match. */
	public SlayerMonster match(String text)
	{
		if (text == null || text.isEmpty())
		{
			return null;
		}
		final String norm = normalize(text);
		final SlayerMonster exact = byName.get(norm);
		if (exact != null)
		{
			return exact;
		}
		for (Map.Entry<String, SlayerMonster> e : byName.entrySet())
		{
			if (norm.contains(e.getKey()))
			{
				return e.getValue();
			}
		}
		return null;
	}

	static String normalize(String s)
	{
		return s.toLowerCase().trim();
	}
}

package com.slayerclog.clog;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.RuneLite;

/**
 * Tracks which collection log items are obtained, from opened log pages and new-item messages.
 * State is persisted per account.
 */
@Slf4j
@Singleton
public class CollectionLogManager
{
	private static final File BASE_DIR = new File(RuneLite.RUNELITE_DIR, "slayer-clog-check");

	private final Client client;
	private final Gson gson;

	// page title -> (item id -> item)
	private final Map<String, Map<Integer, ClogItem>> pages = new HashMap<>();
	// every item id known to be obtained
	private final Set<Integer> obtainedItems = new HashSet<>();

	private long loadedAccountHash = -1L;

	/** On-disk shape. */
	private static final class SaveData
	{
		Map<String, List<ClogItem>> pages;
		List<Integer> obtained;
	}

	@Inject
	private CollectionLogManager(Client client, Gson gson)
	{
		this.client = client;
		this.gson = gson;
	}

	/** Read the open collection log page. Client thread only. */
	public void captureOpenPage()
	{
		final Widget header = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_HEADER);
		final Widget itemsContainer = client.getWidget(ComponentID.COLLECTION_LOG_ENTRY_ITEMS);
		if (header == null || itemsContainer == null)
		{
			return;
		}

		final Widget[] headerChildren = header.getDynamicChildren();
		if (headerChildren == null || headerChildren.length == 0)
		{
			return;
		}

		final String pageTitle = headerChildren[0].getText();
		if (pageTitle == null || pageTitle.isEmpty())
		{
			return;
		}

		final Map<Integer, ClogItem> pageItems = new HashMap<>();
		final Widget[] itemWidgets = itemsContainer.getDynamicChildren();
		if (itemWidgets != null)
		{
			for (Widget w : itemWidgets)
			{
				final int itemId = w.getItemId();
				if (itemId <= 0)
				{
					continue;
				}
				// Opacity 0 means obtained.
				final boolean obtained = w.getOpacity() == 0;
				final int quantity = obtained ? w.getItemQuantity() : 0;
				pageItems.put(itemId, new ClogItem(itemId, obtained, quantity));
				if (obtained)
				{
					obtainedItems.add(itemId);
				}
			}
		}

		if (pageItems.isEmpty())
		{
			return;
		}

		pages.put(pageKey(pageTitle), pageItems);
		save();
	}

	/** Record an item as obtained. */
	public void markObtained(int itemId)
	{
		if (itemId > 0 && obtainedItems.add(itemId))
		{
			save();
		}
	}

	/** TRUE obtained, FALSE not obtained, null if unknown. */
	public Boolean isObtained(String pageTitle, int itemId)
	{
		if (obtainedItems.contains(itemId))
		{
			return Boolean.TRUE;
		}
		final Map<Integer, ClogItem> page = pages.get(pageKey(pageTitle));
		if (page == null)
		{
			return null;
		}
		final ClogItem item = page.get(itemId);
		return item != null && item.isObtained();
	}

	/** Logged quantity, or 0. */
	public int getQuantity(String pageTitle, int itemId)
	{
		final Map<Integer, ClogItem> page = pages.get(pageKey(pageTitle));
		if (page == null)
		{
			return 0;
		}
		final ClogItem item = page.get(itemId);
		return item == null ? 0 : item.getQuantity();
	}

	/** Load saved state for an account. */
	public void load(long accountHash)
	{
		pages.clear();
		obtainedItems.clear();
		loadedAccountHash = accountHash;
		if (accountHash == -1L)
		{
			return;
		}

		final File file = saveFile(accountHash);
		if (!file.exists())
		{
			return;
		}

		try
		{
			final String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
			final JsonObject root = new JsonParser().parse(json).getAsJsonObject();
			final SaveData data;
			if (root.has("pages") || root.has("obtained"))
			{
				data = gson.fromJson(root, SaveData.class);
			}
			else
			{
				// Legacy format: the object was the pages map.
				data = new SaveData();
				data.pages = gson.fromJson(root,
					new com.google.gson.reflect.TypeToken<Map<String, List<ClogItem>>>()
					{
					}.getType());
			}
			if (data != null && data.pages != null)
			{
				for (Map.Entry<String, List<ClogItem>> entry : data.pages.entrySet())
				{
					final Map<Integer, ClogItem> page = new HashMap<>();
					for (ClogItem item : entry.getValue())
					{
						page.put(item.getId(), item);
						if (item.isObtained())
						{
							obtainedItems.add(item.getId());
						}
					}
					pages.put(pageKey(entry.getKey()), page);
				}
			}
			if (data != null && data.obtained != null)
			{
				obtainedItems.addAll(data.obtained);
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to load collection log save file", e);
		}
	}

	private void save()
	{
		if (loadedAccountHash == -1L)
		{
			return;
		}

		final SaveData data = new SaveData();
		data.pages = new HashMap<>();
		for (Map.Entry<String, Map<Integer, ClogItem>> entry : pages.entrySet())
		{
			data.pages.put(entry.getKey(), new ArrayList<>(entry.getValue().values()));
		}
		data.obtained = new ArrayList<>(obtainedItems);

		try
		{
			//noinspection ResultOfMethodCallIgnored
			BASE_DIR.mkdirs();
			Files.write(saveFile(loadedAccountHash).toPath(),
				gson.toJson(data).getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.warn("Failed to save collection log data", e);
		}
	}

	/** Page lookup key: ignores case, spacing and punctuation. */
	static String pageKey(String title)
	{
		return title == null ? "" : title.replaceAll("<[^>]*>", "").toLowerCase().replaceAll("[^a-z0-9]", "");
	}

	private static File saveFile(long accountHash)
	{
		return new File(BASE_DIR, accountHash + ".json");
	}
}

package com.slayerclog.clog;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/** A collection log item and whether it is obtained. */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class ClogItem
{
	private int id;
	private boolean obtained;
	private int quantity;
}

package com.slayerclog;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SlayerClogConfig.GROUP)
public interface SlayerClogConfig extends Config
{
	String GROUP = "slayerclog";

	@ConfigItem(
		keyName = "mortimerView",
		name = "Mortimer comparison",
		description = "When Mortimer's task-selection interface is open, compare the collection log potential of each offered task.",
		position = 1
	)
	default boolean mortimerView()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOnlyUnobtained",
		name = "Only show unobtained",
		description = "Hide items you have already collected, so you only see what's left.",
		position = 2
	)
	default boolean showOnlyUnobtained()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showSuperior",
		name = "Show superior drops",
		description = "Include the Superior section (imbued heart, eternal gem, dust and mist battlestaff) in the task and Mortimer tables.",
		position = 3
	)
	default boolean showSuperior()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showDropRates",
		name = "Show drop rates",
		description = "Show each item's drop rate in brackets under its name, for example (1:4000).",
		position = 4
	)
	default boolean showDropRates()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showQuantities",
		name = "Show quantities",
		description = "Show how many of each obtained item you have logged.",
		position = 5
	)
	default boolean showQuantities()
	{
		return true;
	}
}
